<script setup>
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import {state,api,go,notify,applyLanguage} from '../store';
import Icon from './Icon.vue';
import AvatarCropper from './AvatarCropper.vue';
const copy=(en,id)=>state.language==='id'?id:en;
const ownerId=state.user?.id;let disposed=false;
const loading=ref(true),saving=ref(false),error=ref(''),errors=ref({}),editing=ref(false),account=ref(null),photoMaxKb=ref(2048),fileInput=ref(null),cropFile=ref(null),stagedPhoto=ref(null),preview=ref(''),removePhoto=ref(false),removeDialog=ref(null),removeOpen=ref(false),photoError=ref('');
const form=ref({name:'',email:''}),password=ref({current_password:'',password:'',password_confirmation:''}),visible=ref({current_password:false,password:false,password_confirmation:false});
const photoFailed=ref(false);
const passwordRequired=computed(()=>!!state.user?.must_change_password);
const tab=computed(()=>passwordRequired.value||new URLSearchParams(state.query).get('tab')==='password'?'password':'profile');
const user=computed(()=>account.value||state.user||{}),initials=computed(()=>String((editing.value?form.value.name:user.value.name)||'INBAF').trim().split(/\s+/).filter(Boolean).slice(0,2).map(part=>Array.from(part)[0]).join('').toUpperCase());
const participant=computed(()=>user.value.role==='participant');
const displayRole=computed(()=>participant.value?'Participant':'Superadmin');
const accountStatus=computed(()=>user.value.active?copy('Active','Aktif'):copy('Inactive','Tidak aktif'));
const participantFields=computed(()=>[{name:'country',label:copy('Country of origin','Negara asal'),autocomplete:'country-name',max:120},{name:'nationality',label:copy('Nationality','Kewarganegaraan'),max:120},{name:'native_language',label:copy('Native language','Bahasa ibu'),max:120},{name:'institution',label:copy('Institution','Institusi'),max:200},{name:'phone',label:copy('Phone number','Nomor telepon'),type:'tel',autocomplete:'tel',max:32}]);
const genderOptions=computed(()=>[{value:'female',label:copy('Female','Perempuan')},{value:'male',label:copy('Male','Laki-laki')},{value:'non_binary',label:copy('Non-binary','Nonbiner')},{value:'prefer_not_to_say',label:copy('Prefer not to say','Tidak ingin menyebutkan')}]);
const genderLabel=computed(()=>genderOptions.value.find(option=>option.value===user.value.profile?.gender)?.label||copy('Not provided','Belum diisi'));
const languageLabel=computed(()=>(user.value.preferred_language||state.language)==='id'?'Bahasa Indonesia':'English');
const emptyValue=computed(()=>copy('Not provided','Belum diisi'));
const historyNotice=computed(()=>copy('Profile name changes apply to your account. They do not change names recorded on completed test results or issued certificates. Certificate name corrections require an authorized, audited process.','Perubahan nama profil berlaku untuk akun Anda. Nama pada hasil tes yang telah selesai dan sertifikat yang sudah diterbitkan tetap tersimpan. Koreksi nama sertifikat harus melalui proses berwenang dan tercatat dalam audit.'));
const photoSource=computed(()=>editing.value?(removePhoto.value?'':preview.value||user.value.avatar_url):user.value.avatar_url),shownPhoto=computed(()=>photoFailed.value?'':photoSource.value);
watch(photoSource,()=>{photoFailed.value=false});
const requirements=computed(()=>[{valid:Array.from(password.value.password).length>=8,label:copy('At least 8 characters','Minimal 8 karakter')},{valid:/\p{Ll}/u.test(password.value.password)&&/\p{Lu}/u.test(password.value.password),label:copy('Uppercase and lowercase letters','Huruf besar dan huruf kecil')},{valid:/\p{N}/u.test(password.value.password),label:copy('A number','Angka')},{valid:/[\p{Z}\p{S}\p{P}]/u.test(password.value.password),label:copy('A symbol','Simbol')},{valid:new TextEncoder().encode(password.value.password).length<=72,label:copy('No more than 72 bytes','Tidak lebih dari 72 byte')}] );
const complexity=computed(()=>requirements.value.every(item=>item.valid));
const strength=computed(()=>{const length=Array.from(password.value.password).length;if(!length)return {progress:0,label:copy('Enter a new password','Masukkan password baru'),level:'empty'};if(!complexity.value)return {progress:Math.min(65,requirements.value.filter(item=>item.valid).length*18),label:copy('Needs improvement','Perlu diperkuat'),level:'weak'};if(length<12)return {progress:80,label:copy('Good','Baik'),level:'good'};return {progress:100,label:copy('Strong','Kuat'),level:'strong'}});
const passwordFields=computed(()=>[{name:'current_password',label:copy('Current Password','Password saat ini'),autocomplete:'current-password'},{name:'password',label:copy('New Password','Password baru'),autocomplete:'new-password'},{name:'password_confirmation',label:copy('Confirm New Password','Konfirmasi password baru'),autocomplete:'new-password'}]);
function formatDate(value){return value?new Intl.DateTimeFormat(state.language==='id'?'id-ID':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):copy('Not available','Belum tersedia')}
function formatBirthDate(value){if(!value)return emptyValue.value;const date=new Date(String(value).slice(0,10)+'T00:00:00');return Number.isNaN(date.getTime())?emptyValue.value:new Intl.DateTimeFormat(state.language==='id'?'id-ID':'en-GB',{dateStyle:'long'}).format(date)}
function today(){const value=new Date();return [value.getFullYear(),String(value.getMonth()+1).padStart(2,'0'),String(value.getDate()).padStart(2,'0')].join('-')}
function clearPreview(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';stagedPhoto.value=null;removePhoto.value=false;cropFile.value=null;photoError.value='';}
function resetForm(){clearPreview();const profile=user.value.profile||{};form.value={name:user.value.name||'',email:user.value.email||'',country:profile.country||'',nationality:profile.nationality||'',native_language:profile.native_language||'',institution:profile.institution||'',phone:profile.phone||'',date_of_birth:profile.date_of_birth?.slice(0,10)||'',gender:profile.gender||'',preferred_language:user.value.preferred_language||state.language||'en'};editing.value=false;errors.value={};error.value='';}
function edit(){resetForm();editing.value=true;nextTick(()=>document.querySelector('#account-name')?.focus())}
function finishEdit(){resetForm();if(participant.value&&tab.value==='profile'&&new URLSearchParams(state.query).get('edit')==='1')go('/profile')}
function clearPassword(){password.value={current_password:'',password:'',password_confirmation:''};visible.value={current_password:false,password:false,password_confirmation:false};}
function selectTab(next){if(saving.value||passwordRequired.value&&next!=='password')return;go(next==='password'?'/profile?tab=password':'/profile')}
function syncRequestedEdit(){if(participant.value&&account.value&&tab.value==='profile'&&new URLSearchParams(state.query).get('edit')==='1')edit()}
watch(()=>state.query,()=>{resetForm();clearPassword();syncRequestedEdit()});
function fieldError(field){return (errors.value[field]||[]).join(' ')}
function dismissError(field){delete errors.value[field];error.value=''}
function updateUser(value){if(disposed||!value||state.user?.id!==ownerId||value.id!==ownerId)return false;account.value=value;state.user={...state.user,...value};return true;}
async function load(){loading.value=true;error.value='';try{const response=await api('/account');if(!updateUser(response.user))return;photoMaxKb.value=Number(response.photo_max_kb)||2048;resetForm();syncRequestedEdit()}catch(e){if(!disposed)error.value=e.message}finally{loading.value=false}}
function choosePhoto(){if(!saving.value){photoError.value='';fileInput.value?.click()}}
function selectedPhoto(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;photoError.value='';delete errors.value.photo;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||!/^.+\.(jpe?g|png|webp)$/i.test(file.name)){photoError.value=copy('Choose a JPG, JPEG, PNG or WebP photo.','Pilih foto JPG, JPEG, PNG, atau WebP.');return}if(file.size>photoMaxKb.value*1024){photoError.value=copy('The photo must be '+(photoMaxKb.value/1024)+' MB or smaller.','Ukuran foto maksimal '+(photoMaxKb.value/1024)+' MB.');return}cropFile.value=file;}
function acceptCrop(file){if(file.size>photoMaxKb.value*1024){photoError.value=copy('The cropped photo is too large. Please choose another photo.','Hasil potongan foto terlalu besar. Pilih foto lain.');cropFile.value=null;return}if(preview.value)URL.revokeObjectURL(preview.value);stagedPhoto.value=file;preview.value=URL.createObjectURL(file);removePhoto.value=false;cropFile.value=null;photoError.value='';}
async function confirmRemoval(){removeOpen.value=true;await nextTick();if(!disposed&&removeDialog.value)removeDialog.value.showModal()}
function closeRemoval(){removeDialog.value?.close();removeOpen.value=false}
function stageRemoval(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';stagedPhoto.value=null;removePhoto.value=true;photoError.value='';closeRemoval()}
async function saveProfile(){saving.value=true;errors.value={};error.value='';try{const body=new FormData();body.append('_method','PUT');body.append('name',form.value.name.trim());body.append('email',form.value.email.trim());if(participant.value)for(const field of ['country','nationality','native_language','institution','phone','date_of_birth','gender','preferred_language'])body.append(field,String(form.value[field]||'').trim());if(stagedPhoto.value)body.append('photo',stagedPhoto.value);else if(removePhoto.value)body.append('remove_photo','1');const response=await api('/account',{method:'POST',body});if(!updateUser(response.user))return;if(participant.value)applyLanguage(response.user.preferred_language);finishEdit();notify(copy('Your profile has been updated.','Profil Anda berhasil diperbarui.'))}catch(e){if(!disposed){errors.value=e.data?.errors||{};error.value=e.message}}finally{saving.value=false}}
async function savePassword(){const wasRequired=passwordRequired.value;errors.value={};error.value='';if(!complexity.value){errors.value.password=[copy('Use 8 or more characters, up to 72 bytes, with uppercase, lowercase, a number and a symbol.','Gunakan minimal 8 karakter, maksimal 72 byte, dengan huruf besar, huruf kecil, angka, dan simbol.')];return}if(password.value.password===password.value.current_password){errors.value.password=[copy('The new password must be different from your current password.','Password baru harus berbeda dari password saat ini.')];return}if(password.value.password!==password.value.password_confirmation){errors.value.password_confirmation=[copy('The password confirmation does not match.','Konfirmasi password tidak cocok.')];return}saving.value=true;try{const response=await api('/account/password',{method:'PUT',body:{...password.value}});if(!updateUser(response.user))return;clearPassword();if(wasRequired)go('/dashboard');notify(copy('Your password has been changed. Other sessions have been signed out.','Password Anda berhasil diubah. Sesi login lainnya telah diakhiri.'))}catch(e){if(!disposed){errors.value=e.data?.errors||{};error.value=e.message}}finally{saving.value=false}}
onMounted(load);
onBeforeUnmount(()=>{disposed=true;clearPreview();clearPassword();removeDialog.value?.close()});
</script>

<template>
<section class="account-page" :class="{'participant-account':participant}">
 <div class="page-heading"><div><div class="eyebrow"><span></span>{{copy('YOUR ACCOUNT','AKUN ANDA')}}</div><h1>{{copy('My Profile','Profil Saya')}}</h1><p>{{copy('Manage your personal details and keep your account secure.','Kelola informasi pribadi dan jaga keamanan akun Anda.')}}</p></div><span class="account-security"><Icon name="ShieldCheck" :size="20"/>{{copy('Secure account','Akun terlindungi')}}</span></div>
 <div v-if="error" class="inline-error" role="alert">{{error}}</div>
 <div v-if="passwordRequired" class="account-note password-required" role="status"><Icon name="LockKeyhole" :size="24"/><p>{{copy('Change your initial password to continue. Use the password supplied by your administrator as your current password.','Ganti password awal untuk melanjutkan. Masukkan password dari administrator sebagai password saat ini.')}}</p></div>
 <div v-if="loading" class="panel loading-panel" role="status"><span class="loader"></span>{{copy('Loading your profile…','Memuat profil Anda…')}}</div>
 <div v-else-if="!account" class="panel empty-state"><Icon name="CircleAlert" :size="38"/><p>{{copy('Your profile could not be loaded.','Profil Anda belum dapat dimuat.')}}</p><button class="button" @click="load">{{copy('Try again','Coba lagi')}}</button></div>
 <div v-else class="account-layout">
  <aside class="account-summary account-card"><div class="account-avatar" :class="{pending:preview||removePhoto}"><img v-if="shownPhoto" :src="shownPhoto" @error="photoFailed=true" :alt="copy('Profile photo','Foto profil')"><span v-else aria-hidden="true">{{initials}}</span><span class="avatar-check"><Icon name="ShieldCheck" :size="18"/></span></div><h2>{{user.name}}</h2><p v-if="participant" class="account-nationality"><Icon name="Globe2" :size="18"/>{{user.profile?.nationality||user.profile?.country||copy('Your INBAF learning journey','Perjalanan belajar Anda bersama INBAF')}}</p><p class="account-email">{{user.email}}</p><span class="account-role"><Icon name="BadgeCheck" :size="17"/>{{displayRole}}</span><span v-if="participant" class="account-status" :class="{inactive:!user.active}"><span></span>{{accountStatus}}</span>
   <div v-if="editing&&tab==='profile'" class="account-photo-actions"><input ref="fileInput" class="account-file" type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" :aria-label="copy('Choose profile photo','Pilih foto profil')" tabindex="-1" @change="selectedPhoto"><button type="button" class="button secondary full" :disabled="saving" @click="choosePhoto"><Icon name="Upload" :size="18"/>{{participant&&!shownPhoto?copy('Upload Photo','Unggah Foto'):copy('Change Photo','Ganti Foto')}}</button><button v-if="shownPhoto" type="button" class="text-button remove-photo" :disabled="saving" @click="confirmRemoval"><Icon name="Trash2" :size="18"/>{{copy('Remove Photo','Hapus Foto')}}</button><small>{{copy('JPG, JPEG, PNG or WebP · Max. ','JPG, JPEG, PNG, atau WebP · Maks. ')}}{{photoMaxKb/1024}} MB</small><p v-if="preview||removePhoto" class="photo-pending" role="status"><Icon name="Clock3" :size="17"/>{{copy('Photo changes will be saved with your profile.','Perubahan foto disimpan bersama profil.')}}</p><p v-if="photoError||fieldError('photo')" class="account-field-error" role="alert">{{photoError||fieldError('photo')}}</p></div>
   <nav class="account-tabs" :aria-label="copy('Account settings','Pengaturan akun')"><button :class="{active:tab==='profile'}" :aria-current="tab==='profile'?'page':undefined" :disabled="saving||passwordRequired" @click="selectTab('profile')"><Icon name="CircleUserRound" :size="20"/>{{copy('My Profile','Profil Saya')}}<Icon name="ChevronRight" :size="17"/></button><button :class="{active:tab==='password'}" :aria-current="tab==='password'?'page':undefined" :disabled="saving" @click="selectTab('password')"><Icon name="LockKeyhole" :size="20"/>{{copy('Change Password','Ubah Password')}}<Icon name="ChevronRight" :size="17"/></button></nav>
   <div class="account-privacy"><Icon name="ShieldCheck" :size="21"/><p>{{copy('Your role and access permissions are managed securely by the system.','Role dan hak akses Anda dikelola dengan aman oleh sistem.')}}</p></div>
   <dl v-if="participant" class="participant-account-dates"><div><dt>{{copy('Registered','Terdaftar')}}</dt><dd>{{formatDate(user.created_at)}}</dd></div><div><dt>{{copy('Last login','Terakhir login')}}</dt><dd>{{formatDate(user.last_login_at)}}</dd></div></dl>
  </aside>
  <section v-if="tab==='profile'&&participant" class="account-card account-details participant-details">
   <div class="account-card-heading"><div><span class="account-section-icon"><Icon name="CircleUserRound" :size="23"/></span><h2>{{copy('Personal Information','Informasi Pribadi')}}</h2><p>{{copy('Your details, your learning journey. Keep them up to date.','Informasi Anda dan perjalanan belajar Anda. Pastikan selalu akurat.')}}</p></div><button v-if="!editing" class="button secondary" @click="edit"><Icon name="PenLine" :size="18"/>{{copy('Edit Profile','Edit Profil')}}</button></div>
   <form v-if="editing" class="account-edit-form participant-edit-form" :aria-busy="saving" @submit.prevent="saveProfile">
    <div class="form-grid participant-form-grid">
     <label for="account-name">{{copy('Full name','Nama lengkap')}}<input id="account-name" v-model="form.name" autocomplete="name" required maxlength="120" :disabled="saving" :aria-invalid="!!fieldError('name')" :aria-describedby="fieldError('name')?'account-name-error':undefined" @input="dismissError('name')"><span v-if="fieldError('name')" id="account-name-error" class="account-field-error">{{fieldError('name')}}</span></label>
     <label v-for="field in participantFields" :key="field.name" :for="'account-'+field.name">{{field.label}}<input :id="'account-'+field.name" v-model="form[field.name]" :type="field.type||'text'" :autocomplete="field.autocomplete" :maxlength="field.max" :disabled="saving" :aria-invalid="!!fieldError(field.name)" :aria-describedby="fieldError(field.name)?'account-'+field.name+'-error':undefined" @input="dismissError(field.name)"><span v-if="fieldError(field.name)" :id="'account-'+field.name+'-error'" class="account-field-error">{{fieldError(field.name)}}</span></label>
     <label for="account-date_of_birth">{{copy('Date of birth','Tanggal lahir')}}<input id="account-date_of_birth" v-model="form.date_of_birth" type="date" autocomplete="bday" :max="today()" :disabled="saving" :aria-invalid="!!fieldError('date_of_birth')" :aria-describedby="fieldError('date_of_birth')?'account-date_of_birth-error':undefined" @input="dismissError('date_of_birth')"><span v-if="fieldError('date_of_birth')" id="account-date_of_birth-error" class="account-field-error">{{fieldError('date_of_birth')}}</span></label>
     <label for="account-gender">{{copy('Gender (optional)','Jenis kelamin (opsional)')}}<select id="account-gender" v-model="form.gender" :disabled="saving" :aria-invalid="!!fieldError('gender')" :aria-describedby="fieldError('gender')?'account-gender-error':undefined" @change="dismissError('gender')"><option value="">{{copy('Not provided','Belum diisi')}}</option><option v-for="option in genderOptions" :key="option.value" :value="option.value">{{option.label}}</option></select><span v-if="fieldError('gender')" id="account-gender-error" class="account-field-error">{{fieldError('gender')}}</span></label>
    </div>
    <div class="participant-section-heading"><Icon name="Settings2" :size="21"/><h3>{{copy('Account Settings','Pengaturan Akun')}}</h3></div>
    <div class="form-grid participant-form-grid"><label for="account-email">{{copy('Email address','Alamat email')}}<input id="account-email" v-model="form.email" type="email" autocomplete="email" required maxlength="254" :disabled="saving" :aria-invalid="!!fieldError('email')" :aria-describedby="fieldError('email')?'account-email-error':undefined" @input="dismissError('email')"><span v-if="fieldError('email')" id="account-email-error" class="account-field-error">{{fieldError('email')}}</span></label><label for="account-preferred_language">{{copy('Preferred interface language','Bahasa antarmuka pilihan')}}<select id="account-preferred_language" v-model="form.preferred_language" :disabled="saving" :aria-invalid="!!fieldError('preferred_language')" :aria-describedby="fieldError('preferred_language')?'account-preferred_language-error':undefined" @change="dismissError('preferred_language')"><option value="en">English</option><option value="id">Bahasa Indonesia</option></select><span v-if="fieldError('preferred_language')" id="account-preferred_language-error" class="account-field-error">{{fieldError('preferred_language')}}</span></label></div>
    <div class="account-readonly-role"><Icon name="LockKeyhole" :size="18"/><span>{{copy('Account role','Role akun')}}: <strong>Participant</strong></span><span class="muted">{{copy('Read only','Hanya dapat dilihat')}}</span></div>
    <div class="account-note participant-history-note"><Icon name="ShieldCheck" :size="20"/><p>{{historyNotice}}</p></div>
    <div class="account-actions"><button type="button" class="button secondary" :disabled="saving" @click="finishEdit">{{copy('Cancel','Batal')}}</button><button class="button account-primary" :disabled="saving"><Icon :name="saving?'LoaderCircle':'Check'" :size="18"/>{{saving?copy('Saving…','Menyimpan…'):copy('Save Changes','Simpan Perubahan')}}</button></div>
   </form>
   <template v-else>
    <dl class="account-info participant-info"><div><dt>{{copy('Full name','Nama lengkap')}}</dt><dd>{{user.name}}</dd></div><div v-if="user.username"><dt>{{copy('Username','Nama pengguna')}}</dt><dd>{{user.username}}</dd></div><div v-for="field in participantFields" :key="field.name"><dt>{{field.label}}</dt><dd>{{user.profile?.[field.name]||emptyValue}}</dd></div><div><dt>{{copy('Date of birth','Tanggal lahir')}}</dt><dd>{{formatBirthDate(user.profile?.date_of_birth)}}</dd></div><div><dt>{{copy('Gender (optional)','Jenis kelamin (opsional)')}}</dt><dd>{{genderLabel}}</dd></div></dl>
    <div class="participant-section-heading"><Icon name="Settings2" :size="21"/><h3>{{copy('Account Settings','Pengaturan Akun')}}</h3></div>
    <dl class="account-info participant-info"><div><dt>{{copy('Email address','Alamat email')}}</dt><dd>{{user.email}}</dd></div><div><dt>{{copy('Preferred interface language','Bahasa antarmuka pilihan')}}</dt><dd>{{languageLabel}}</dd></div><div><dt>{{copy('Account role','Role akun')}}</dt><dd><span class="account-role"><Icon name="BadgeCheck" :size="17"/>Participant</span></dd></div><div><dt>{{copy('Account status','Status akun')}}</dt><dd>{{accountStatus}}</dd></div></dl>
    <div class="account-note"><Icon name="ShieldCheck" :size="20"/><p>{{historyNotice}}</p></div>
   </template>
   <div class="participant-security-settings"><div class="participant-section-heading"><Icon name="LockKeyhole" :size="21"/><h3>{{copy('Security Settings','Pengaturan Keamanan')}}</h3></div><p>{{copy('Protect your account with a strong, unique password.','Lindungi akun Anda dengan password yang kuat dan unik.')}}</p><a href="/profile?tab=password" class="button secondary" :aria-disabled="saving" @click.prevent="selectTab('password')"><Icon name="LockKeyhole" :size="18"/>{{copy('Change Password','Ubah Password')}}</a></div>
  </section>
  <section v-else-if="tab==='profile'" class="account-card account-details"><div class="account-card-heading"><div><span class="account-section-icon"><Icon name="CircleUserRound" :size="23"/></span><h2>{{copy('Personal information','Informasi pribadi')}}</h2><p>{{copy('Your details as they appear across INBAF.','Informasi Anda yang ditampilkan di seluruh INBAF.')}}</p></div><button v-if="!editing" class="button secondary" @click="edit"><Icon name="PenLine" :size="18"/>{{copy('Edit Profile','Edit Profil')}}</button></div>
   <form v-if="editing" class="account-edit-form" :aria-busy="saving" @submit.prevent="saveProfile"><div class="form-grid"><label for="account-name">{{copy('Full name','Nama lengkap')}}<input id="account-name" v-model="form.name" autocomplete="name" required maxlength="120" :disabled="saving" :aria-invalid="!!fieldError('name')" :aria-describedby="fieldError('name')?'account-name-error':undefined" @input="dismissError('name')"><span v-if="fieldError('name')" id="account-name-error" class="account-field-error">{{fieldError('name')}}</span></label><label for="account-email">{{copy('Email address','Alamat email')}}<input id="account-email" v-model="form.email" type="email" autocomplete="email" required maxlength="254" :disabled="saving" :aria-invalid="!!fieldError('email')" :aria-describedby="fieldError('email')?'account-email-error':undefined" @input="dismissError('email')"><span v-if="fieldError('email')" id="account-email-error" class="account-field-error">{{fieldError('email')}}</span></label></div><div class="account-readonly-role"><Icon name="LockKeyhole" :size="18"/><span>{{copy('Account role','Role akun')}}: <strong>Superadmin</strong></span><span class="muted">{{copy('Read only','Hanya dapat dilihat')}}</span></div><div class="account-actions"><button type="button" class="button secondary" :disabled="saving" @click="resetForm">{{copy('Cancel','Batal')}}</button><button class="button account-primary" :disabled="saving"><Icon :name="saving?'LoaderCircle':'Check'" :size="18"/>{{saving?copy('Saving…','Menyimpan…'):copy('Save Changes','Simpan Perubahan')}}</button></div></form>
   <dl v-else class="account-info"><div><dt>{{copy('Full name','Nama lengkap')}}</dt><dd>{{user.name}}</dd></div><div><dt>{{copy('Email address','Alamat email')}}</dt><dd>{{user.email}}</dd></div><div><dt>{{copy('Account role','Role akun')}}</dt><dd><span class="account-role"><Icon name="BadgeCheck" :size="17"/>Superadmin</span></dd></div><div><dt>{{copy('Account created','Akun dibuat')}}</dt><dd>{{formatDate(user.created_at)}}</dd></div><div><dt>{{copy('Last login','Terakhir login')}}</dt><dd>{{formatDate(user.last_login_at)}}</dd></div></dl>
   <div class="account-note"><Icon name="CircleHelp" :size="20"/><p>{{copy('Updates to your name and photo appear immediately in the account menu.','Perubahan nama dan foto langsung tampil di menu akun.')}}</p></div>
