  <section v-else class="account-card account-details"><div class="account-card-heading"><div><span class="account-section-icon"><Icon name="LockKeyhole" :size="23"/></span><h2>{{copy('Change Password','Ubah Password')}}</h2><p>{{copy('Choose a unique password to protect your account.','Pilih password unik untuk melindungi akun Anda.')}}</p></div></div>
